// ── HERO ──────────────────────────────────────────────────────────
import React, { useEffect, useRef, useState } from "react";
import SplitText from "../components/SplitText";
import { useViewport } from "../context/ViewportContext";

const HERO_WORDS = [
  "In a world of infinite generation, taste becomes power.",
  "Awakening human potential through creativity, culture & tech",
];

function Hero() {
  const heroRef = useRef(null);
  const videoRef = useRef(null);
  const touchStartYRef = useRef(0);
  const isTransitioningRef = useRef(false);
  const [activeWordIndex, setActiveWordIndex] = useState(0);
  const { isMobile } = useViewport();
  const isFirstWord = activeWordIndex <= 0;
  const isLastWord = activeWordIndex >= HERO_WORDS.length - 1;

  useEffect(() => {
    const hero = heroRef.current;
    if (!hero) return;

    const isHeroActive = () => {
      const rect = hero.getBoundingClientRect();
      return rect.top <= 0 && rect.bottom > window.innerHeight * 0.55;
    };

    const tryChangeWord = (deltaY, event) => {
      if (deltaY === 0 || isTransitioningRef.current || !isHeroActive()) {
        return;
      }

      if (deltaY > 0 && isLastWord) {
        return;
      }

      if (deltaY < 0 && isFirstWord) {
        return;
      }

      event.preventDefault();
      isTransitioningRef.current = true;

      setActiveWordIndex((prev) => {
        if (deltaY > 0) {
          return Math.min(prev + 1, HERO_WORDS.length - 1);
        }

        return Math.max(prev - 1, 0);
      });

      window.setTimeout(() => {
        isTransitioningRef.current = false;
      }, 550);
    };

    const onWheel = (event) => {
      tryChangeWord(event.deltaY, event);
    };

    const onTouchStart = (event) => {
      touchStartYRef.current = event.touches[0]?.clientY ?? 0;
    };

    const onTouchMove = (event) => {
      const currentY = event.touches[0]?.clientY ?? 0;
      const deltaY = touchStartYRef.current - currentY;
      tryChangeWord(deltaY, event);
    };

    window.addEventListener("wheel", onWheel, { passive: false });
    window.addEventListener("touchstart", onTouchStart, { passive: true });
    window.addEventListener("touchmove", onTouchMove, { passive: false });

    return () => {
      window.removeEventListener("wheel", onWheel);
      window.removeEventListener("touchstart", onTouchStart);
      window.removeEventListener("touchmove", onTouchMove);
    };
  }, [isFirstWord, isLastWord]);


  return (
    <section
      ref={heroRef}
      className="section hero"
      id="top"
      style={{
        position: "relative",
        minHeight: "100vh",
        width: "100%",
        display: "flex",
        flexDirection: "column",
        justifyContent: "center",
        alignItems: "center",
        overflow: "hidden",
      }}
      data-screen-label="Hero"
    >
      {/* Background video */}
      <video
        ref={videoRef}
        className="hero__bg-video"
        src={isMobile ? `${process.env.PUBLIC_URL}/assets/videos/VIDEO_movil.mp4` : `${process.env.PUBLIC_URL}/assets/videos/VIDEO_WEB.mp4`}
        autoPlay
        loop
        muted
        playsInline
      />

      <div className="hero__scrim" />

      <div className="hero__content">
        <SplitText
          key={`hero-headline-${activeWordIndex}`}
          tag="h1"
          text={HERO_WORDS[activeWordIndex]}
          className="hero__head horizon reveal"
          splitType="words"
          delay={120}
          initialDelay={0}
          duration={2.5}
          ease="power3.out"
          from={{ opacity: 0, y: 30 }}
          to={{ opacity: 1, y: 0 }}
          threshold={0.1}
          rootMargin="-60px"
          textAlign="left"
          style={{ color: "#ffffff", maxWidth: "1000px", minWidth: "300px" }}
        />
      </div>

      <div className="hero__buttons">

      </div>
    </section>
  );
}

export default Hero;
